let ctx, data, busy=false, owner='', error='', sequence=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(de,en)=>ctx?.language==='en'?en:de;
const date=v=>new Date(v).toLocaleDateString(ctx?.language==='en'?'en-GB':'de-DE');
const statuses={pending:['In Prüfung','Under review'],approved:['Bestätigt','Approved'],rejected:['Abgelehnt','Rejected'],requested:['Angefragt','Requested'],processing:['In Bearbeitung','Processing'],shipped:['Versendet','Shipped'],cancelled:['Storniert','Cancelled']};
const status=s=>tr(...(statuses[s]||[s,s]));
export function rewardsMarkup(){return `<section class="subhero rewards-hero"><div><small>REDSCORE · REDREWARDS</small><h1>Red<span>Rewards</span></h1><h2>${tr('Vorsorge, die sich auszahlt.','Preparedness that rewards you.')}</h2><p>${tr('Lerne dazu, dokumentiere deine Vorbereitung und sammle RewardsPoints für Sachprämien.','Learn, record your preparation and collect RewardsPoints for physical rewards.')}</p></div></section><div class="content-wrap" id="rewards-panel" aria-live="polite"><p>${tr('Punktekonto wird geladen …','Loading your points account …')}</p></div>`;}
async function request(action,payload={},form){if(!navigator.onLine)throw Error(tr('RedRewards benötigt Internet. Punkte und Einlösungen werden nur online bestätigt.','RedRewards needs internet. Points and redemptions are confirmed online only.'));const token=await ctx.token();if(!token)throw Error(tr('Bitte melde dich erneut an.','Please sign in again.'));const r=await fetch('/api/rewards',{method:'POST',headers:{authorization:`Bearer ${token}`,...(!form?{'content-type':'application/json'}:{})},body:form||JSON.stringify({action,data:payload}),signal:AbortSignal.timeout(form?45000:20000)});let result;try{result=await r.json();}catch{throw Error(tr('RedRewards ist vorübergehend nicht erreichbar. Bitte erneut versuchen.','RedRewards is temporarily unavailable. Please try again.'));}if(!r.ok||result.ok===false)throw Error(result.error||tr('Aktion fehlgeschlagen.','Request failed.'));return result;}
const field=(name,label,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const descriptions={score50:['RedScore 50 erreicht','RedScore 50 reached'],profile:['Haushalt eingerichtet','Household set up'],assessment:['Vorsorge-Check abgeschlossen','Preparedness check completed'],supplies:['Wasser und Lebensmittel erfasst','Water and food recorded'],'first-aid':['Erste-Hilfe-Kurs bestätigt','First-aid course approved'],refund:['Prämienpunkte zurückgebucht','Reward points refunded']};
const title=v=>{const k=v.description?.replace('activity:','');if(descriptions[k])return tr(...descriptions[k]);if(v.description?.startsWith('lesson:')){const l=data.lessons.find(l=>l.id===v.description.slice(7));return l?(ctx.language==='en'?l.title_en:l.title):'Lerneinheit';}return v.description;};
function draw(){const root=document.querySelector('#rewards-panel');if(!root)return;
 if(!data){root.innerHTML=`<div class="rr-message" role="alert">${esc(error||tr('Punktekonto wird geladen …','Loading points …'))}</div><button data-rr="refresh" class="outline">${tr('Erneut versuchen','Try again')}</button>`;return;}
 const used=k=>data.ledger.some(v=>v.event_key==='activity:'+k);
 root.innerHTML=`${error?`<p role="alert" class="rr-message">${esc(error)}</p>`:''}<section class="rr-account"><div><small>${tr('DEIN PUNKTEKONTO','YOUR POINTS ACCOUNT')}</small><strong>${data.balance.toLocaleString()} <span>RewardsPoints</span></strong><p>${tr('Serverseitig bestätigt · unabhängig von deinem RedScore','Confirmed on the server · separate from your RedScore')}</p></div><button class="outline" data-rr="refresh">${tr('Aktualisieren','Refresh')}</button></section>
 <div class="rr-grid"><section class="rr-box"><h2>${tr('Deine ersten Punkte','Your first points')}</h2><p>${tr('Jede Aktivität zählt einmal. Angaben müssen zuvor mit deinem Konto synchronisiert sein. Ab einem RedScore von 50 gibt es einmalig 100 Punkte. Ein höherer Score bringt keinen zusätzlichen Score-Bonus. Wiederholte Logins oder bloße Klicks geben keine Punkte.','Each activity counts once. Save and sync your information first. Reaching RedScore 50 earns a one-time 100 points. A higher score does not increase this bonus. Repeated logins and simple clicks do not earn points.')}</p>${[['profile',50],['assessment',100],['supplies',50],['score50',100]].map(([k,n])=>`<article class="rr-activity"><div><b>${tr(...descriptions[k])}</b><small>+${n} RewardsPoints</small></div><button class="outline" data-rr="earn" data-id="${k}" ${used(k)?'disabled':''}>${used(k)?tr('Gutgeschrieben','Credited'):tr('Punkte prüfen','Check points')}</button></article>`).join('')}</section>
 <section class="rr-box"><h2>${tr('Lernen & verstehen','Learn & understand')}</h2><p>${tr('Kurze Lerneinheiten mit Wissenscheck. Einmalige Punkte nach der angegebenen Lernzeit und einer richtigen Antwort. Ergänzende Schulungsvideos werden hier bereitgestellt.','Short lessons with a knowledge check. Earn points once after the stated learning time and a correct answer. Supplementary training videos appear here.')}</p>${data.lessons.map(l=>`<article class="rr-activity"><div><b>${esc(ctx.language==='en'?l.title_en:l.title)}</b><small>+${l.points} RewardsPoints · ${l.video_url?tr('Mit Video','With video'):tr('Kurztraining','Mini lesson')}</small></div><button class="outline" data-rr="lesson" data-id="${esc(l.id)}" ${l.completed?'disabled':''}>${l.completed?tr('Abgeschlossen','Completed'):tr('Starten','Start')}</button></article>`).join('')}</section></div>
 <section class="rr-box"><div class="rr-section-title"><div><small>+300 REWARDSPOINTS</small><h2>${tr('Erste Hilfe lernen. Teilnahme nachweisen.','Learn first aid. Submit your certificate.')}</h2></div><span class="rr-tag">${tr('Manuelle Prüfung','Manual review')}</span></div><p>${tr('Lade eine Teilnahmebestätigung eines Erste-Hilfe-Kurses aus den letzten drei Jahren hoch. Nach Prüfung erhältst du 300 Punkte, höchstens einmal innerhalb von 24 Monaten. Eine Einreichung allein gibt keine Punkte.','Upload a first-aid course certificate from the last three years. After review, receive 300 points, at most once in 24 months. Submission alone does not earn points.')}</p>
 <form data-rr-form="proof" class="rr-proof-form">${field('provider',tr('Kursanbieter','Course provider'),'text','','maxlength="120" minlength="2"')}${field('course_date',tr('Kursdatum','Course date'),'date','','max="'+new Date().toISOString().slice(0,10)+'"')}<label>${tr('Teilnahmebestätigung','Certificate')}<input name="certificate" type="file" accept="application/pdf,image/jpeg,image/png" required><small>PDF, JPG, PNG · max. 3 MB</small></label><label class="rr-consent"><input type="checkbox" required><span>${tr('Ich bestätige meine Teilnahme. Der Nachweis darf zur Prüfung vertraulich durch die RedScore-Verwaltung eingesehen werden. Nicht benötigte Daten bitte vor dem Upload schwärzen.','I confirm my attendance. RedScore administrators may confidentially review this certificate. Redact unnecessary information before uploading.')}</span></label><button class="green">${tr('Nachweis zur Prüfung einreichen','Submit certificate for review')}</button></form>
 ${data.proofs.map(p=>`<article class="rr-activity"><div><b>${esc(p.provider)}</b><small>${date(p.course_date)} · ${status(p.status)}</small>${p.review_note?`<p>${esc(p.review_note)}</p>`:''}</div></article>`).join('')}</section>
 <section class="rr-box"><h2>${tr('Deine Sachprämien','Your physical rewards')}</h2><p>${tr('Die ersten Prämien sind Vorschläge. Einlösen kannst du nur freigegebene Prämien mit vorhandenem Bestand. Versand aktuell innerhalb Deutschlands. RewardsPoints sind nicht auszahlbar oder übertragbar.','The initial rewards are proposals. Only released rewards with stock can be redeemed. Shipping is currently limited to Germany. RewardsPoints cannot be cashed out or transferred.')}</p><div class="rr-prizes">${data.rewards.map(r=>`<article class="rr-prize"><div class="rr-prize-symbol" aria-hidden="true">${r.points>=2000?'▣':r.points>=1000?'✚':'◉'}</div><small>${r.active?tr('Verfügbar','Available'):tr('Prämienvorschlag','Reward proposal')}</small><h3>${esc(ctx.language==='en'?r.name_en:r.name)}</h3><p>${esc(ctx.language==='en'?r.description_en:r.description)}</p><strong>${r.points} RewardsPoints</strong><button class="${r.active&&r.stock>0?'green':'outline'}" data-rr="redeem" data-id="${r.id}" ${!r.active||r.stock<1||data.balance<r.points?'disabled':''}>${!r.active?tr('Noch nicht freigegeben','Not released yet'):r.stock<1?tr('Zurzeit vergriffen','Currently unavailable'):data.balance<r.points?tr('Weitere Punkte sammeln','Collect more points'):tr('Prämie einlösen','Redeem reward')}</button></article>`).join('')}</div></section>
 <div class="rr-grid"><section class="rr-box"><h2>${tr('Punkteverlauf','Points history')}</h2>${data.ledger.length?data.ledger.map(v=>`<article class="rr-activity"><div><b>${esc(title(v))}</b><small>${date(v.created_at)}</small></div><strong>${v.points>0?'+':''}${v.points}</strong></article>`).join(''):`<p>${tr('Hier erscheinen deine bestätigten Gutschriften und Einlösungen.','Confirmed credits and redemptions will appear here.')}</p>`}</section><section class="rr-box"><h2>${tr('Deine Einlösungen','Your redemptions')}</h2>${data.redemptions.length?data.redemptions.map(r=>`<article class="rr-activity"><div><b>${esc(r.reward_name)}</b><small>${date(r.created_at)} · ${r.points} RewardsPoints · ${status(r.status)}</small></div></article>`).join(''):`<p>${tr('Noch keine Prämie eingelöst.','No rewards redeemed yet.')}</p>`}<p>${tr('Fragen zu Prüfung oder Versand?','Questions about review or shipping?')} <a href="mailto:administration@redscore.de">administration@redscore.de</a></p></section></div>${data.admin?adminMarkup():''}`;
 root.querySelectorAll('form').forEach(form=>form.addEventListener('submit',submit));root.querySelectorAll('[data-rr]').forEach(button=>button.addEventListener('click',act));root.setAttribute('aria-busy',String(busy));}
function adminMarkup(){return `<section class="rr-box rr-admin"><small>ADMINISTRATION</small><h2>${tr('RedRewards verwalten','Manage RedRewards')}</h2><h3>${tr('Nachweise in Prüfung','Certificates awaiting review')}</h3>${data.review_queue.length?data.review_queue.map(p=>`<form data-rr-form="review_proof" data-id="${p.id}" class="rr-admin-form"><b>${esc(p.provider)} · ${date(p.course_date)}</b><small>${esc(p.display_name||'')} · ${esc(p.email||'')} · ${esc(p.user_id)}</small><button type="button" class="outline" data-rr="proof" data-id="${p.id}">${tr('Nachweis öffnen','Open certificate')}</button><label>${tr('Entscheidung','Decision')}<select name="status"><option value="approved">${tr('Bestätigen · 300 Punkte','Approve · 300 points')}</option><option value="rejected">${tr('Ablehnen','Reject')}</option></select></label><label>${tr('Hinweis an Mitglied','Note to member')}<input name="note" maxlength="500"></label><button class="green">${tr('Prüfung abschließen','Complete review')}</button></form>`).join(''):`<p>${tr('Keine offenen Nachweise.','No pending certificates.')}</p>`}
 <h3>${tr('Bestand & Freigabe','Stock & release')}</h3>${data.rewards.map(r=>`<form data-rr-form="save_reward" data-id="${r.id}" class="rr-admin-form">${field('name',tr('Prämie / konkretes Modell','Reward / specific model'),'text',r.name,'maxlength="100"')}${field('name_en',tr('Prämie auf Englisch','Reward in English'),'text',r.name_en,'maxlength="100"')}${field('description',tr('Konkreter Prämienumfang','Exact reward contents'),'text',r.description,'maxlength="700"')}${field('description_en',tr('Prämienumfang auf Englisch','Reward contents in English'),'text',r.description_en,'maxlength="700"')}${field('points','RewardsPoints','number',r.points,'min="100" max="100000"')}${field('stock',tr('Verfügbarer Bestand','Available stock'),'number',r.stock,'min="0" max="10000"')}<label class="rr-consent"><input name="active" type="checkbox" ${r.active?'checked':''}>${tr('Für Einlösung freigeben','Release for redemption')}</label><button class="outline">${tr('Speichern','Save')}</button></form>`).join('')}
 <h3>${tr('Schulungsvideos','Training videos')}</h3><p>${tr('Optional: direkte HTTPS-Adresse einer Videodatei ergänzen, für deren Einbindung die Nutzungsrechte vorliegen. Der Wissenscheck bleibt Voraussetzung für Punkte.','Optional: add a direct HTTPS video file URL with permission to embed it. Passing the knowledge check remains required for points.')}</p>${data.lessons.map(l=>`<form data-rr-form="save_video" data-id="${l.id}" class="rr-admin-form"><b>${esc(l.title)}</b><label>Video-URL (DE)<input name="url" type="url" value="${esc(l.video_url||'')}" maxlength="1000" placeholder="https://…"></label><label>Video-URL (EN)<input name="url_en" type="url" value="${esc(l.video_url_en||'')}" maxlength="1000" placeholder="https://…"></label><button class="outline">${tr('Video speichern','Save video')}</button></form>`).join('')}
 <h3>${tr('Versandaufträge','Shipping requests')}</h3>${data.fulfilment.map(r=>`<form data-rr-form="fulfil" data-id="${r.id}" class="rr-admin-form"><b>${esc(r.reward_name)}</b><p>${Object.values(r.shipping).map(esc).join(' · ')}</p><small>${status(r.status)} · ${r.points} RewardsPoints</small><label>Status<select name="status"><option value="processing">${tr('In Bearbeitung','Processing')}</option><option value="shipped">${tr('Versendet','Shipped')}</option><option value="cancelled">${tr('Stornieren und Punkte erstatten','Cancel and refund points')}</option></select></label><button class="green">${tr('Status speichern','Save status')}</button></form>`).join('')||`<p>${tr('Keine offenen Versandaufträge.','No open shipping requests.')}</p>`}</section>`;}
async function refresh(){const expectedOwner=owner,seq=++sequence;try{const result=await request('snapshot');if(expectedOwner!==owner||seq!==sequence)return;data=result;error='';}catch(e){if(expectedOwner!==owner||seq!==sequence)return;data=null;error=e.message;}draw();}
function message(dialog,text){const p=dialog.querySelector('[role=alert]');p.textContent=text;p.hidden=false;}
function dialog(content){const el=document.createElement('dialog');el.className='rr-dialog';el.innerHTML=`<button class="rr-close" aria-label="${tr('Schließen','Close')}">×</button>${content}<p role="alert" hidden></p>`;document.body.append(el);el.querySelector('.rr-close').onclick=()=>{el.close();el.remove()};el.addEventListener('cancel',()=>el.remove());el.showModal();return el;}

function safeMediaUrl(value){try{const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password)return '';if(['www.redscore.de','redscore.de'].includes(url.hostname)&&url.pathname.startsWith('/media/training/'))return new URL(url.pathname,location.origin).href;return url.href;}catch{return '';}}
async function openLesson(id){
 const meta=await request('start_lesson',{lesson:id});
 const lesson=data.lessons.find(item=>item.id===id),en=ctx.language==='en';
 const videoUrl=safeMediaUrl(en?(lesson.video_url_en||lesson.video_url):lesson.video_url);
 const sourceUrl=safeMediaUrl(lesson.source_url)||'https://www.bbk.bund.de/DE/Warnung-Vorsorge/Vorsorge/vorsorge_node.html';
 const seconds=Number(lesson.min_seconds)||30;
 const elapsed=meta.started_at?Math.max(0,(Date.now()-Date.parse(meta.started_at))/1000):0;
 const remaining=Math.max(0,Math.ceil(seconds-elapsed));
 const el=dialog(`<small>+${lesson.points} REWARDSPOINTS</small><h2>${esc(en?lesson.title_en:lesson.title)}</h2>
 ${videoUrl?`<div class="rr-video-intro"><p>${tr('RedScore-Schulungsvideo · mit Ton und Untertiteln','RedScore training video · with audio and captions')}</p><button class="green" data-play-video>${tr('Schulungsvideo öffnen','Open training video')}</button><div data-video-slot></div></div>`:''}
 <details class="rr-lesson-text" ${videoUrl?'':'open'}><summary>${tr('Lerninhalt als Text','Read the lesson')}</summary><p>${esc(en?lesson.body_en:lesson.body)}</p></details>
 <a href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">${tr('Fachliche Grundlagen','Source guidance')} ↗</a>
 <form data-lesson-answer><fieldset><legend>${esc(en?lesson.question_en:lesson.question)}</legend>${(en?lesson.options_en:lesson.options).map((option,index)=>`<label class="rr-option"><input type="radio" name="answer" value="${index}" required>${esc(option)}</label>`).join('')}</fieldset>
 <p data-wait>${tr(`Nimm dir Zeit für die Lerneinheit. Der Wissenscheck ist nach ${seconds} Sekunden Lernzeit verfügbar.`,`Take time to study. The knowledge check becomes available after ${seconds} seconds of learning time.`)}</p><button class="green" disabled>${tr('Antwort prüfen und Punkte erhalten','Check answer and earn points')}</button></form>`);
 if(videoUrl)el.classList.add('rr-video-dialog');
 const unlock=()=>{if(!el.isConnected)return;el.querySelector('form button').disabled=false;el.querySelector('[data-wait]').textContent=tr('Du kannst die Antwort jetzt prüfen.','You can check your answer now.');};
 const timer=setTimeout(unlock,remaining*1000);if(!remaining)unlock();
 const stop=()=>{clearTimeout(timer);el.querySelector('video')?.pause();};el.addEventListener('close',stop);el.addEventListener('cancel',stop);
 el.querySelector('[data-play-video]')?.addEventListener('click',event=>{
  const video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';if(lesson.subtitles_url||lesson.subtitles_url_en)video.crossOrigin='anonymous';video.src=videoUrl;
  const poster=safeMediaUrl(en?(lesson.video_poster_en||lesson.video_poster):lesson.video_poster);if(poster)video.poster=poster;
  for(const lang of ['de','en']){
   const url=safeMediaUrl(lang==='en'?lesson.subtitles_url_en:lesson.subtitles_url);if(!url)continue;
   const track=document.createElement('track');track.kind='captions';track.srclang=lang;track.label=lang==='de'?'Deutsch':'English';track.src=url;video.append(track);
  }
  el.querySelector('[data-video-slot]').append(video);event.currentTarget.remove();
  video.play().catch(()=>{/* Native controls remain available if playback needs another tap. */});
 });
 el.querySelector('form').onsubmit=async event=>{
  event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;
  try{await request('complete_lesson',{lesson:id,answer:Number(new FormData(event.target).get('answer'))});el.close();el.remove();await refresh();}
  catch(error){message(el,error.message);button.disabled=false;}
 };
}

async function act(event){event.preventDefault();event.stopPropagation();if(busy)return;const button=event.currentTarget,{rr,id}=button.dataset;error='';busy=true;button.disabled=true;try{
 if(rr==='refresh')return await refresh();
 if(rr==='earn'){await request('earn',{activity:id});await refresh();}
 if(rr==='lesson')await openLesson(id);
 if(rr==='redeem'){const reward=data.rewards.find(r=>r.id===id);const key=crypto.randomUUID();const el=dialog(`<h2>${esc(reward.name)}</h2><p>${reward.points} RewardsPoints · ${tr('Die Punkte werden bei erfolgreicher Einlösung abgebucht.','Points are deducted when redemption succeeds.')}</p><form>${field('name',tr('Vor- und Nachname','Full name'),'text','','autocomplete="name" maxlength="120"')}${field('street',tr('Straße und Hausnummer','Street and house number'),'text','','autocomplete="street-address" maxlength="160"')}${field('postal_code',tr('Postleitzahl','Postcode'),'text','','pattern="[0-9]{5}" inputmode="numeric" autocomplete="postal-code"')}${field('city',tr('Ort','Town'),'text','','autocomplete="address-level2" maxlength="100"')}<p>${tr('Versandland: Deutschland. Die Adresse wird nur für die Prämienabwicklung gespeichert.','Shipping country: Germany. Your address is stored only for reward fulfilment.')}</p><label class="rr-consent"><input type="checkbox" required>${tr('Prämie verbindlich mit RewardsPoints einlösen.','Confirm redemption using RewardsPoints.')}</label><button class="green">${tr('Jetzt einlösen','Redeem now')}</button></form>`);el.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await request('redeem',{reward_id:id,request_key:key,shipping:{...Object.fromEntries(new FormData(e.target)),country:'DE'}});el.close();el.remove();await refresh();}catch(err){message(el,err.message);b.disabled=false;}};}
 if(rr==='proof'){const result=await request('proof_url',{id});const a=document.createElement('a');a.href=result.url;a.target='_blank';a.rel='noopener noreferrer';a.click();}
 }catch(e){error=e.message;draw();}finally{busy=false;if(button.isConnected)button.disabled=false;}}
async function submit(event){event.preventDefault();event.stopPropagation();if(busy)return;busy=true;const form=event.currentTarget,b=form.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;try{const values=Object.fromEntries(new FormData(form));const action=form.dataset.rrForm;if(action==='proof'){const certificate=form.elements.certificate.files[0];if(!certificate||certificate.size>3*1024*1024)throw Error(tr('Bitte eine Datei bis 3 MB wählen.','Please choose a file up to 3 MB.'));await request('',{},new FormData(form));}else await request(action,{...values,id:form.dataset.id,...(action==='save_reward'?{active:form.elements.active.checked}:{} )});error='';await refresh();}catch(e){error=e.message;const box=document.createElement('p');box.className='rr-message';box.setAttribute('role','alert');box.textContent=error;form.querySelector('.rr-message')?.remove();form.append(box);}finally{busy=false;if(b?.isConnected)b.disabled=false;}}
export function mountRewards(options){ctx=options;if(owner!==options.owner){owner=options.owner;data=null;error='';}refresh();}
export function setRewardsLanguage(language){ctx={...ctx,language};}

export function resetRewards(){if(!owner)return;sequence++;owner="";data=null;busy=false;error="";document.querySelectorAll(".rr-dialog").forEach(el=>{el.close();el.remove()});}
